
export const DEBOUNCE_MS = 800;
export const MAX_WAIT_MS = 4000;

const REQUIRED_DEPS = [
  'store', 'exportTurtle', 'opfsWrite', 'sparqlUpdate', 'updateStatements', 'onError',
];

function graphName(source) {
  const g = source && source.graph;
  if (g == null) return '';
  return g.value != null ? String(g.value) : String(g);
}

function groupByGraph(delta) {
  const groups = new Map();
  const fill = (quads, field) => {
    for (const q of quads || []) {
      const g = q && q.graph && q.graph.value ? q.graph.value : '';
      let group = groups.get(g);
      if (!group) { group = { added: [], removed: [] }; groups.set(g, group); }
      group[field].push(q);
    }
  };
  fill(delta && delta.added, 'added');
  fill(delta && delta.removed, 'removed');
  return groups;
}

// ONE QUEUE PER SOURCE. Without it a slow update is overtaken by the next and an
// INSERT can land before its matching DELETE.
export function makeSourceSync(sources, deps = {}) {
  const {
    store, exportTurtle, opfsWrite, sparqlUpdate, updateStatements,
    onError, onSkip = null,
    setTimeout: schedule = ((fn, ms) => globalThis.setTimeout(fn, ms)),
    now = Date.now,
    debounceMs = DEBOUNCE_MS,
    maxWaitMs = MAX_WAIT_MS,
  } = deps;

  const missing = REQUIRED_DEPS.filter((name) => deps[name] == null);
  if (missing.length) {
    throw new Error('makeSourceSync: missing deps: ' + missing.join(', '));
  }

  const sourceByGraph = new Map();
  for (const source of sources || []) {
    const g = graphName(source);
    if (g && !sourceByGraph.has(g)) sourceByGraph.set(g, source);
  }

  const waiting = new Map();
  const generations = new Map();

  const chain = new Map();

  function enqueue(source, task) {
    const prev = chain.get(source) || Promise.resolve();
    const next = prev.then(task, task);
    chain.set(source, next);
    next.then(() => { if (chain.get(source) === next) chain.delete(source); });
    return next;
  }

  const newGeneration = (source) => {
    const generation = (generations.get(source) || 0) + 1;
    generations.set(source, generation);
    return generation;
  };

  const reportError = (source, error, group) => {
    const inverse = { added: group.removed, removed: group.added };
    if (typeof onError !== 'function') throw error;
    onError(source, error, inverse);
  };

  async function writeTtl(source, generation) {
    const state = waiting.get(source);
    if (!state || state.generation !== generation) return;
    waiting.delete(source);
    try {
      const ttl = exportTurtle(store, { graph: graphName(source) });
      await opfsWrite(source.opfs, ttl);
    } catch (e) {
      reportError(source, e, state);
    }
  }

  function scheduleTtl(source, group) {
    const state = waiting.get(source) || { added: [], removed: [], first: now() };
    state.added.push(...group.added);
    state.removed.push(...group.removed);
    const generation = newGeneration(source);
    state.generation = generation;
    waiting.set(source, state);
    const left = state.first + maxWaitMs - now();
    const wait = Math.max(0, Math.min(debounceMs, left));
    schedule(() => enqueue(source, () => writeTtl(source, generation)), wait);
  }

  async function toEndpoint(source, group) {
    let outcome;
    try {
      outcome = updateStatements({ added: group.added, removed: group.removed });
    } catch (e) {
      reportError(source, e, group);
      return;
    }
    const { query = '', skipped = 0 } = outcome || {};
    if (query) {
      try {
        await sparqlUpdate(source.updateUrl, query);
      } catch (e) {
        reportError(source, e, group);
        return;
      }
    }
    if (skipped && typeof onSkip === 'function') onSkip(source, skipped);
  }

  async function process(delta) {
    for (const [graph, group] of groupByGraph(delta)) {
      const source = sourceByGraph.get(graph);
      if (!source) {
        reportError(null, new Error('source sync: a change in a graph without a source'
          + (graph ? ` ("${graph}")` : ' (default graph)')
          + ' — nowhere to write it to'), group);
        continue;
      }
      if (source.mode !== 'readwrite') {
        reportError(source, new Error(`source sync: source "${source.url || graph}" is read-only`
          + ' — the change cannot be saved'), group);
        continue;
      }
      if (source.kind === 'ttl') {
        if (!source.opfs) {
          reportError(source, new Error(`source sync: source "${source.url || graph}" has no`
            + ' local copy (opfs) to write to'), group);
          continue;
        }
        scheduleTtl(source, group);
      }
      else if (source.kind === 'sparql') {
        await enqueue(source, () => toEndpoint(source, group));
      }
      else {
        reportError(source, new Error(`source sync: unknown sourceKind "${source.kind}"`
          + ` for "${source.url || graph}"`), group);
      }
    }
  }

  function flush(source) {
    const targets = source ? [source] : new Set([...waiting.keys(), ...chain.keys()]);
    const promises = [];
    for (const b of targets) {
      const state = waiting.get(b);
      if (!state) {
        promises.push(chain.get(b) || Promise.resolve());
        continue;
      }
      const generation = newGeneration(b);
      state.generation = generation;
      promises.push(enqueue(b, () => writeTtl(b, generation)));
    }
    return Promise.all(promises).then(() => undefined);
  }

  return { process, flush };
}
